import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);
        String[] parts = reader.readLine().split(" ");
        int N = Integer.parseInt(parts[0]);
        long K = Long.parseLong(parts[1]);

        if (K >= N) {
            out.println(0);
            out.close();
            return;
        }
        int C = (int) (N - K);

        long[] factorials = new long[200001];
        factorials[0] = 1;
        for (int i = 1; i <= 200000; i++) {
            factorials[i] = (factorials[i - 1] * i) % 998244353L;
        }

        long answer = 0;
        int sign = 1;
        for (int i = C; i > 0; i--) {
            long val = (nCr(C, i, factorials) * power(i, N, 998244353L)) % 998244353L;
            answer = (answer + sign * val + 998244353L * 2) % 998244353L;
            sign *= -1;
        }

        long mult = 2 * nCr(N, C, factorials);
        if (C == N)
            mult = 1L;
        out.println((answer * mult) % 998244353L);
        out.close();
    }

    static long nCr(int n, int r, long[] fact) {
        long denom = (fact[r] * fact[n - r]) % 998244353L;
        long denomInv = power(denom, 998244353L - 2, 998244353L);
        return (fact[n] * denomInv) % 998244353L;
    }

    static long power(long base, int exp, long mod) {
        long res = 1L;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1)
                res = (res * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return res;
    }
}
